    private static String monopolyTop3Text(JSONArray jSONArray) {
        if (jSONArray == null || jSONArray.length() == 0) {
            return "";
        }
        String currentUid = UserIdMap.getCurrentUid();
        StringBuilder sb = new StringBuilder();
        int i = 0;
        for (int i2 = 0; i2 < jSONArray.length() && i < 3; i2++) {
            JSONObject jSONObjectOptJSONObject = jSONArray.optJSONObject(i2);
            if (jSONObjectOptJSONObject != null) {
                int iOptInt = jSONObjectOptJSONObject.optInt("stepCount", 0);
                int iOptInt2 = jSONObjectOptJSONObject.optInt("medalCount", 0);
                int iOptInt3 = jSONObjectOptJSONObject.optInt("mapCount", 0);
                if (iOptInt <= 0 && iOptInt2 <= 0 && iOptInt3 <= 0) {
                    break;
                }
                String strOptString = jSONObjectOptJSONObject.optString("userId");
                sb.append("/[");
                sb.append(UserIdMap.getShowName(strOptString));
                if (strOptString.equals(currentUid)) {
                    sb.append("(本人)");
                }
                sb.append("]");
                sb.append(iOptInt);
                sb.append("步");
                i++;
            }
        }
        return sb.length() == 0 ? "" : sb.substring(1);
    }

    private void collectPKEnergy() {
        try {
            JSONObject jSONObject = new JSONObject(AntForestRpcCall.queryTopEnergyChallengeRanking());
            if (!MessageUtil.checkResultCode(TAG + "获取PK排行榜失败:", jSONObject).booleanValue()) {
                Log.error("获取PK排行榜失败: " + jSONObject.optString("resultDesc"));
                return;
            }
            if (!jSONObject.getString("rankMemberStatus").equals("JOIN")) {
                Log.record("未加入PK排行榜");
                return;
            }
            collectFriendsEnergy(jSONObject, "PK");
            JSONArray jSONArrayOptJSONArray = jSONObject.optJSONArray("totalData");
            if (jSONArrayOptJSONArray != null && jSONArrayOptJSONArray.length() != 0) {
                ArrayList arrayList = new ArrayList();
                for (int i = 20; i < jSONArrayOptJSONArray.length(); i++) {
                    String string = jSONArrayOptJSONArray.getJSONObject(i).getString("userId");
                    if (!Objects.equals(string, this.selfId)) {
                        arrayList.add(string);
                        if (arrayList.size() == 20) {
                            collectFriendsEnergy(arrayList, "PK");
                            arrayList.clear();
                        }
                    }
                }
                if (!arrayList.isEmpty()) {
                    collectFriendsEnergy(arrayList, "PK");
                }
                Log.record("收取PK能量完成！");
                return;
            }
            Log.record("PK好友排行榜为空，跳过");
        } catch (Exception e) {
            Log.printStackTrace(TAG, e);
        }
    }

    private void notifyMain() {
        if (this.taskCount.decrementAndGet() < 1) {
            synchronized (this) {
                notifyAll();
            }
        }
    }

