    private void photoGuangPan(String str) {
        try {
            JSONObject jSONObject = new JSONObject(EcoLifeRpcCall.queryDish("renwuGD", str));
            String str2 = TAG;
            if (MessageUtil.checkResultCode(str2, jSONObject).booleanValue()) {
                HashMap map = new HashMap();
                JSONObject jSONObjectOptJSONObject = jSONObject.optJSONObject("data");
                if (jSONObjectOptJSONObject != null) {
                    String strOptString = jSONObjectOptJSONObject.optString("beforeMealsImageUrl");
                    String strOptString2 = jSONObjectOptJSONObject.optString("afterMealsImageUrl");
                    if (!StringUtil.isEmpty(strOptString) && !StringUtil.isEmpty(strOptString2)) {
                        Pattern patternCompile = Pattern.compile("img/(.*)/original");
                        Matcher matcher = patternCompile.matcher(strOptString);
                        if (matcher.find()) {
                            map.put("BEFORE_MEALS", matcher.group(1));
                        }
                        Matcher matcher2 = patternCompile.matcher(strOptString2);
                        if (matcher2.find()) {
                            map.put("AFTER_MEALS", matcher2.group(1));
                        }
                        TokenConfig.saveDishImage(map);
                    }
                }
                if ("SUCCESS".equals(jSONObject.getJSONObject("data").getString(NotificationCompat.CATEGORY_STATUS))) {
                    return;
                }
                Map<String, String> randomDishImage = TokenConfig.getRandomDishImage();
                if (randomDishImage == null) {
                    Log.forest("光盘行动💿请先完成一次光盘打卡");
                    return;
                }
                if (MessageUtil.checkResultCode(str2, new JSONObject(EcoLifeRpcCall.uploadBeforeMealsDishImage(randomDishImage.get("BEFORE_MEALS"), str))).booleanValue() && MessageUtil.checkResultCode(str2, new JSONObject(EcoLifeRpcCall.uploadAfterMealsDishImage(randomDishImage.get("AFTER_MEALS"), str))).booleanValue()) {
                    JSONObject jSONObject2 = new JSONObject(EcoLifeRpcCall.tick("photoguangpan", str, "renwuGD"));
                    if (MessageUtil.checkResultCode(str2, jSONObject2).booleanValue()) {
                        String string = jSONObject2.getJSONObject("data").getString("toastMsg");
                        Toast.show("光盘行动💿打卡完成#" + string);
                        Log.forest("光盘行动💿打卡完成#" + string + "[" + UserIdMap.getShowName(UserIdMap.getCurrentUid()) + "]");
                    }
                }
            }
        } catch (Throwable th) {
            String str3 = TAG;
            Log.i(str3, "photoGuangPan err:");
            Log.printStackTrace(str3, th);
        }
    }

