    private Boolean exchangeBenefit(String str) {
        int i;
        if (this.skuInfo.isEmpty()) {
            getAllSkuInfo();
        }
        JSONObject jSONObject = this.skuInfo.get(str);
        if (jSONObject == null) {
            Log.record("活力兑换🎐找不到要兑换的权益！");
            return false;
        }
        try {
            String string = jSONObject.getString("skuName");
            JSONArray jSONArray = jSONObject.getJSONArray("itemStatusList");
            while (i < jSONArray.length()) {
                String string2 = jSONArray.getString(i);
                i = (ItemStatus.REACH_LIMIT.name().equals(string2) || ItemStatus.NO_ENOUGH_POINT.name().equals(string2) || ItemStatus.NO_ENOUGH_STOCK.name().equals(string2)) ? 0 : i + 1;
                Log.record("活力兑换🎐[" + string + "]停止:" + ItemStatus.valueOf(string2).nickName());
                if (ItemStatus.REACH_LIMIT.name().equals(string2)) {
                    Status.flagToday("forest::exchangeLimit::" + str);
                }
                return false;
            }
            String string3 = jSONObject.getString("spuId");
            if (exchangeBenefit(string3, str, string).booleanValue()) {
                return true;
            }
            getSkuInfoBySpuId(string3);
            return false;
        } catch (Throwable th) {
            String str2 = TAG;
            Log.i(str2, "exchangeBenefit err:");
            Log.printStackTrace(str2, th);
        }
    }

    public static Boolean exchangeBenefit(String str, String str2, String str3) {
        try {
            if (exchangeBenefit(str, str2).booleanValue()) {
                Status.vitalityExchangeBenefitToday(str2);
                Log.forest("活力兑换🎐[" + str3 + "]#第" + Status.getVitalityExchangeBenefitCountToday(str2) + "次");
                return true;
            }
        } catch (Throwable th) {
            String str4 = TAG;
            Log.i(str4, "exchangeBenefit err:");
            Log.printStackTrace(str4, th);
        }
        return false;
    }

    private static Boolean exchangeBenefit(String str, String str2) {
        try {
            JSONObject jSONObject = new JSONObject(AntForestRpcCall.exchangeBenefit(str, str2));
            if (jSONObject.has("errorMessage") && jSONObject.optString("errorMessage").equals("系统繁忙，请稍后再试。")) {
                Status.flagToday("forest::exchangeLimit::" + str2);
            }
            return MessageUtil.checkResultCode(TAG, jSONObject);
        } catch (Throwable th) {
            String str3 = TAG;
            Log.i(str3, "exchangeBenefit err:");
            Log.printStackTrace(str3, th);
            return false;
        }
    }

